import{z as E,x as p,o as t,c,q as o,j as r,D as a,d as n,s as d,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"init 与用户空间","description":"","frontmatter":{"title":"init 与用户空间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/init-userspace.md","filePath":"cs/init-userspace.md","lastUpdated":1791413859000}'),B={name:"cs/init-userspace.md"};function A(m,e,u,h,f,_){const s=p("Mermaid");return t(),c("div",null,[e[2]||(e[2]=o('<h1 id="init-与用户空间" tabindex="-1">init 与用户空间 <a class="header-anchor" href="#init-与用户空间" aria-label="Permalink to &quot;init 与用户空间&quot;">​</a></h1><div class="epigraph"><p>内核创建的第一个用户进程是 pid 1：它不得退出；负责挂载真根、拉起服务，并收养孤儿。</p><footer>—— 据 Unix 传统 init；Stevens；systemd 作为当代实现的对照整理</footer></div><p><a href="/cs/early-boot">上一课</a>把 CPU 交到能 <code>exec</code> 用户程序的点。<a href="/cs/process-image">进程映像</a> 的孤儿由 init 收养，当时是前瞻。缺口是 <strong>pid 1 的义务</strong>：不是某个发行版的单元文件百科，而是内核与用户空间的契约——退出则 panic、等待僵尸、按策略启动其余作业。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核不应内置「如何启动图形界面」。它 <code>exec</code> 配置指定的 init（或 <code>/sbin/init</code>）。init 切换根、按依赖启动 getty、网络、sshd。子进程退出必须 <code>wait</code>，否则僵尸堆积。缺口：这是用户态策略，内核只保证 pid 1 特殊（不可杀于普通 OOM 策略之外、信号受限）。systemd、SysV init、busybox 都是这一角色的实现。</p><p><span class="marginnote">双用户空间（如恢复壳）仍是某个 pid 1。容器里的「init」可以是该 pid 命名空间的 1 号，内核课下一课 namespaces 才切。</span></p><p><span class="marginnote">术语翻译：「僵尸进程」就是已经退出、但没人对它调用 wait 的进程——进程表项还挂着，只剩一行「我结束了」。僵尸堆积的代价很实际：每个僵尸占一个进程号，耗尽后系统连新进程都开不出来。</span></p><p><span class="marginnote">常见误区：初学者容易以为 init 是内核的一部分。实际上它只是内核 exec 的第一个普通用户程序——把 systemd 换成 busybox init，内核一行不改照样跑。内核只保证「1 号进程特殊」，做什么全由这个用户态程序自己决定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>kernel_init</code> 路径 exec 用户程序。该程序：<code>mount</code> 真根、<code>chroot</code>/<code>pivot_root</code>、打开 tty、fork 服务。关机：init 收服务、同步磁盘、通知内核 reboot。与 <a href="/cs/fsync">fsync</a>/writeback 的接头：关机必须刷脏页。不要把桌面会话管理写进内核义务。</p>',10)),(t(),r(l,null,{default:a(()=>[d(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%20rest_init%22%5D%20--%3E%20P1%5B%22exec%20pid%201%22%5D%0A%20%20P1%20--%3E%20ROOT%5B%22%E6%8C%82%E7%9C%9F%E6%A0%B9%22%5D%0A%20%20P1%20--%3E%20SVC%5B%22%E6%8B%89%E8%B5%B7%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20P1%20--%3E%20WAIT%5B%22wait%20%E5%AD%A4%E5%84%BF%E4%B8%8E%E5%83%B5%E5%B0%B8%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[n("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,"init 把「机器可用」从内核对象变成用户策略：同一内核可变成服务器或嵌入式器具。OOM 杀 pid 1 会导致内核认为用户空间已死。tty 的 getty 由 init 拉起，登录后 shell 的控制终端上一课已讲。本课不比较发行版谁更正确。",-1)),e[5]||(e[5]=i("p",null,"孤儿是怎样被收养的：",-1)),(t(),r(l,null,{default:a(()=>[d(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%E8%BF%9B%E7%A8%8B%E5%85%88%E9%80%80%E5%87%BA%22%5D%20--%3E%20C%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E8%BF%98%E5%9C%A8%E8%BF%90%E8%A1%8C%EF%BC%9A%E6%88%90%E4%B8%BA%E5%AD%A4%E5%84%BF%22%5D%0A%20%20C%20--%3E%20A%5B%22%E5%86%85%E6%A0%B8%E6%8A%8A%E5%AE%83%E7%9A%84%E7%88%B6%E8%BF%9B%E7%A8%8B%E5%8F%B7%E6%94%B9%E5%86%99%E6%88%90%201%22%5D%0A%20%20A%20--%3E%20W%5B%22pid%201%20%E8%B0%83%E7%94%A8%20wait%20%E6%94%B6%E5%89%B2%22%5D%0A%20%20W%20--%3E%20OK%5B%22%E8%BF%9B%E7%A8%8B%E8%A1%A8%E9%A1%B9%E9%87%8A%E6%94%BE%EF%BC%8C%E4%B8%8D%E7%95%99%E5%83%B5%E5%B0%B8%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<p><span class="marginnote">为什么重要：关机顺序做错会丢数据。init 要先通知服务退出、把脏页刷进磁盘（fsync/回写），最后才告诉内核重启；跳过前两步直接断电，文件系统日志再稳也可能留下没落盘的写入。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cgroup 的委托全文（下一课）。不把云-init 当内核接口。下一课：同一内核上切出多套「看起来像独立机器」的名字——pid、挂载、网络等命名空间。</p><p>后课默认：一台机器有一个全局 pid 1。把 pid/mnt/net 等名字隔离，下一课 namespaces。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>pid 1 是用户空间根：挂根、启服务、收养孤儿。</li><li>内核几乎不内置服务策略。</li><li>名字隔离是 namespaces 的缺口。</li><li>出处：Unix init 传统；Stevens；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const D=E(B,[["render",A]]);export{x as __pageData,D as default};
